renderSettings=async function(){
  if(!state.project)return renderQueue();
  let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}
  const actions=`<button class="button" id="editProject">${t('editProject')}</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}${t('syncRecentCommits')}</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${t(grant?'changeGitAccess':'automaticGitSetup')}</button>`;
  const grantDetails=grant?`<dl class="simple-setting-rows"><div><dt>${t('status')}</dt><dd><span class="setting-state blue">${t('connected')}</span></dd></div><div><dt>${t('repository')}</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>${t('provider')}</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>${t('accessLevel')}</dt><dd>${t(grant.accessLevel)}</dd></div><div><dt>${t('syncMode')}</dt><dd>${t('onDemand')}</dd></div></dl>`:`<div class="simple-empty-setting"><span class="setting-state">${t('notConnected')}</span><strong>${t('noRepositoryGrant')}</strong></div>`;
  $('#workspace').innerHTML=header(t('settings'),escapeHTML(state.project.name),actions)+`<div class="content simple-settings-page project-simple-settings">
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>${t('gitRepository')}</h2></header>${grantDetails}
    </section>
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>${t('repositoryAndBranches')}</h2><span class="setting-state">${t('version',{version:state.project.configVersion})}</span></header>
      <dl class="simple-setting-rows"><div><dt>${t('repositoryURL')}</dt><dd>${escapeHTML(state.project.repositoryUrl)}</dd></div><div><dt>${t('defaultBranch')}</dt><dd>${escapeHTML(state.project.defaultTargetBranch)}</dd></div><div><dt>${t('allowedBranches')}</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', ')||t('notSet'))}</dd></div></dl>
    </section>
  </div>`;
  $('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(t('syncResult',{fetched:result.fetched,inserted:result.inserted}))}catch(error){toast(error.message)}finally{sync.disabled=false}};
};

function taskModeLabel(mode){
  if(mode==='manual')return state.locale==='zh'?'人工':'Manual';
  if(mode==='human')return t('human');
  if(mode==='agent')return t('agent');
  return mode||t('notSet');
}

function taskDate(value){
  if(!value)return t('notSet');
  const date=new Date(value);
  if(Number.isNaN(date.valueOf()))return value;
  return new Intl.DateTimeFormat(state.locale==='zh'?'zh-CN':'en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(date);
}

async function loadTaskActors(){
  if(!state.project)return [];
  try{
    const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);
    return [
      ...members.filter(member=>member.role).map(member=>({id:member.id,kind:'human',name:member.displayName,available:member.status==='active'})),
      ...agents.map(agent=>({id:agent.id,kind:'agent',name:agent.name,available:agent.status==='active'&&agent.enabled}))
    ];
  }catch{return []}
}

function taskAssignee(item,actors){
  return actors.find(actor=>actor.kind===item.assignee_kind&&actor.id===item.assignee_id)||{id:item.assignee_id||'',kind:item.assignee_kind||'',name:item.assignee_kind?t(item.assignee_kind):t('unassigned'),available:false};
}

function taskAvatar(name,fallback='?'){
  return escapeHTML((name||fallback).trim().slice(0,1).toUpperCase()||fallback);
}

function taskRowMarkup(item,actors,options={}){
  const assignee=taskAssignee(item,actors);
  const row=`<${options.parent?'div':'button'} class="work-item work-row ${state.queuePreview===item.id?'selected':''}" data-id="${item.id}" ${options.parent?'role="button" tabindex="0"':''}>
    <i class="priority-bar ${item.priority}"></i>
    <span class="work-main">
      <span class="work-line">${options.parent?`<button class="parent-toggle ${options.open?'open':''}" type="button" data-toggle-parent="${item.id}" aria-label="${t(options.open?'collapseChildren':'expandChildren')}">${icon('chevron')}</button>`:''}<span class="work-id">${escapeHTML(item.id)}</span>${options.parent?badge(t('parentItem',{completed:options.completed,total:options.total})):badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}</span>
      <strong class="work-item-title">${escapeHTML(item.title)}</strong>
      <span class="work-meta">${options.parent?`<span>${t(item.stage)}</span><i>·</i><span>${t('blockedChildren',{count:options.blocked})}</span>`:`<span>${t('discussionMode')} ${taskModeLabel(item.discussion_mode)}</span><i>·</i><span>${t('executionMode')} ${taskModeLabel(item.execution_mode)}</span>`}<i>·</i><span>${escapeHTML(item.target_branch)}</span><i>·</i><span>${taskDate(item.updated_at)}</span></span>
    </span>
    <span class="work-side"><span class="task-avatar" title="${escapeHTML(assignee.name)}">${taskAvatar(assignee.name,item.assignee_kind==='agent'?'A':'H')}</span>${badge(t(item.priority))}</span>
  </${options.parent?'div':'button'}>`;
  if(!options.parent)return row;
  return `<div class="parent-item">${row}<div class="child-list" ${options.open?'':'hidden'}>${options.children.map(child=>taskRowMarkup(child,actors,{child:true})).join('')}</div></div>`;
}

renderQueue=async function(){
  if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}
  const [items,actors]=await Promise.all([api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`),loadTaskActors()]);
  state.items=items;
  if(state.task){await renderTask();return}
  state.queueStage=state.queueStage||'all';state.queueMine=Boolean(state.queueMine);state.queueQuery=state.queueQuery||'';state.queuePriority=state.queuePriority||'all';state.queueBlocker=state.queueBlocker||'any';state.expandedParents=state.expandedParents||new Set();
  const stageTabs=[['all','queueAll'],['todo','todo'],['discussion','discussion'],['execution','execution'],['acceptance','acceptance'],['completed','completed'],['abandoned','abandoned']];
  const filterActive=state.queuePriority!=='all'||state.queueBlocker!=='any';
  const queueTabs=stageTabs.map(([stage,label])=>[stage,label,stage==='all'?items.length:items.filter(item=>item.stage===stage).length]);
  const toolbar=`<div class="app-page-toolbar queue-tools"><label class="search">${icon('search')}<input id="queueSearch" value="${escapeHTML(state.queueQuery)}" placeholder="${t('search')}"></label><button class="button ${state.queueMine?'active':''}" id="mineToggle" aria-pressed="${state.queueMine}">${t('queueMine')}</button><button class="button ${filterActive?'active':''}" id="queueFilter">${icon('filter')}${t(filterActive?'filterActive':'filter')}</button><span class="queue-count">${t('itemsCount',{count:items.length})}</span></div>`;
  $('#workspace').innerHTML=header(t('queue'),`${state.project.name} · ${state.project.repositoryUrl}`,`<button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button>`)+pageTabs(queueTabs,state.queueStage,'queue-stage',t('queueView'))+pageContent(`${toolbar}<div class="queue-content" id="queueList"></div>`,'queue-page-content');
  const paint=()=>{
    const query=state.queueQuery.trim().toLowerCase();
    const matches=item=>(state.queueStage==='all'||item.stage===state.queueStage)&&(!state.queueMine||(item.assignee_kind==='human'&&item.assignee_id===state.me.id))&&(state.queuePriority==='all'||item.priority===state.queuePriority)&&(state.queueBlocker==='any'||(state.queueBlocker==='blocked')===Boolean(item.blocked_at))&&(!query||`${item.id} ${item.title}`.toLowerCase().includes(query));
    const childrenByParent=new Map();items.forEach(item=>{if(item.parent_id){const children=childrenByParent.get(item.parent_id)||[];children.push(item);childrenByParent.set(item.parent_id,children)}});
    const roots=items.filter(item=>!item.parent_id||!items.some(candidate=>candidate.id===item.parent_id));
    const visibleRoots=roots.map(item=>({item,children:(childrenByParent.get(item.id)||[]).filter(matches)})).filter(entry=>matches(entry.item)||entry.children.length);
    const groupFor=entry=>entry.children.length||childrenByParent.has(entry.item.id)?'parentWork':entry.item.blocked_at?'needsAttention':!entry.item.assignee_id?'unassignedWork':entry.item.stage==='completed'?'completedWork':entry.item.stage==='abandoned'?'abandonedWork':'activeWork';
    const order=['needsAttention','activeWork','unassignedWork','parentWork','completedWork','abandonedWork'];
    const groups=order.map(label=>[label,visibleRoots.filter(entry=>groupFor(entry)===label)]).filter(([,group])=>group.length);
    $('#queueList').innerHTML=groups.length?groups.map(([label,group])=>`<section class="queue-group"><div class="group-label">${t(label)} <span>${group.length}</span></div>${group.map(entry=>{const allChildren=childrenByParent.get(entry.item.id)||[];return taskRowMarkup(entry.item,actors,allChildren.length?{parent:true,children:entry.children,open:state.expandedParents.has(entry.item.id),completed:allChildren.filter(child=>child.stage==='completed').length,total:allChildren.length,blocked:allChildren.filter(child=>child.blocked_at).length}:{})}).join('')}</section>`).join(''):`<section class="queue-empty"><strong>${t('noMatchingItems')}</strong><p>${t('noMatchingItemsNote')}</p></section>`;
    document.querySelectorAll('.work-row[data-id]').forEach(row=>{row.onclick=()=>{const item=items.find(candidate=>candidate.id===row.dataset.id);state.queuePreview=item.id;document.querySelectorAll('.work-row.selected').forEach(selected=>selected.classList.remove('selected'));row.classList.add('selected');taskPreview(item,actors)};if(row.getAttribute('role')==='button')row.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();row.click()}}});
    document.querySelectorAll('[data-toggle-parent]').forEach(button=>button.onclick=event=>{event.stopPropagation();const id=button.dataset.toggleParent;state.expandedParents.has(id)?state.expandedParents.delete(id):state.expandedParents.add(id);paint()});
  };
  paint();
  $('#newItem').onclick=workItemForm;
  $('#queueSearch').oninput=event=>{state.queueQuery=event.target.value;paint()};
  $('#mineToggle').onclick=()=>{state.queueMine=!state.queueMine;renderQueue()};
  $('#queueFilter').onclick=queueFilterForm;
  document.querySelectorAll('[data-queue-stage]').forEach(button=>button.onclick=()=>{state.queueStage=button.dataset.queueStage;renderQueue()});
};

function queueFilterForm(){
  openDrawer(t('filterWorkItems'),`<form class="form" id="queueFilterForm"><label class="field"><span>${t('priority')}</span><select name="priority"><option value="all">${t('allPriorities')}</option>${['urgent','high','medium','low'].map(value=>`<option value="${value}" ${state.queuePriority===value?'selected':''}>${t(value)}</option>`).join('')}</select></label><label class="field"><span>${t('blockerFilter')}</span><select name="blocker"><option value="any">${t('anyBlocker')}</option><option value="blocked" ${state.queueBlocker==='blocked'?'selected':''}>${t('blockedOnly')}</option><option value="unblocked" ${state.queueBlocker==='unblocked'?'selected':''}>${t('unblockedOnly')}</option></select></label><button class="button primary" type="submit">${t('applyFilters')}</button></form>`,()=>{$('#queueFilterForm').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));state.queuePriority=data.priority;state.queueBlocker=data.blocker;closeDrawer();renderQueue()}});
}

function taskPreview(item,actors){
  const assignee=taskAssignee(item,actors),terminal=['completed','abandoned'].includes(item.stage),criteria=(item.acceptance_criteria_markdown||'').split(/\r?\n/).filter(Boolean);
  openDrawer(t('taskDetails'),`<section class="task-preview"><div class="task-preview-id">${escapeHTML(item.id)} · ${t('version',{version:item.version})}</div><h3>${escapeHTML(item.title)}</h3><div class="task-preview-badges">${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.priority))}</div><p class="task-preview-description">${escapeHTML(item.description_markdown||t('noDescription'))}</p><div class="task-preview-actions"><button class="button primary" id="openFullTask">${t('openFullItem')}</button><button class="button" id="previewMessage">${t('sendMessage')}</button>${terminal?'':`<button class="button" id="previewAssign">${t('changeExecutor')}</button>`}</div><dl class="task-preview-kv"><div><dt>${t('currentStage')}</dt><dd>${t(item.stage)}</dd></div><div><dt>${t('executor')}</dt><dd>${escapeHTML(assignee.name)}</dd></div><div><dt>${t('discussionMode')}</dt><dd>${taskModeLabel(item.discussion_mode)}</dd></div><div><dt>${t('executionMode')}</dt><dd>${taskModeLabel(item.execution_mode)}</dd></div><div><dt>${t('acceptanceMode')}</dt><dd>${taskModeLabel(item.acceptance_mode)}</dd></div><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div></dl>${item.blocked_at?`<section class="task-preview-section"><h4>${t('blocker')}</h4><div class="task-preview-blocker"><strong>${taskDate(item.blocked_at)}</strong><p>${escapeHTML(item.blocked_reason||t('blocked'))}</p></div></section>`:''}<section class="task-preview-section"><h4>${t('acceptanceStandards')}</h4>${criteria.length?criteria.map(criterion=>`<div class="preview-criterion"><i></i><span>${escapeHTML(criterion)}</span></div>`).join(''):`<p>${t('noCriteria')}</p>`}</section></section>`,()=>{$('#openFullTask').onclick=()=>{state.task=item.id;closeDrawer();renderQueue()};$('#previewMessage').onclick=()=>messageForm(item);const assign=$('#previewAssign');if(assign)assign.onclick=()=>taskAssignmentForm(item,actors)});
}

function taskEventText(event){
  const payload=event.payload||(()=>{try{return JSON.parse(event.payload_json||'{}')}catch{return {}}})();
  const value=payload.markdown||payload.noteMarkdown||payload.reason||payload.summaryMarkdown||payload.goalMarkdown||payload.message;
  return value||JSON.stringify(payload,null,2);
}

function taskEventAuthor(event,actors){
  if(event.author_type==='system'||!event.author_type)return t('systemAuthor');
  return actors.find(actor=>actor.kind===event.author_type&&actor.id===event.author_id)?.name||event.author_type;
}

function taskEventMarkup(event,actors){
  const author=taskEventAuthor(event,actors);
  return `<article class="conversation-entry"><span class="entry-avatar">${taskAvatar(author,'·')}</span><div class="entry-content"><div class="entry-head"><strong>${escapeHTML(author)}</strong><time>${taskDate(event.created_at)}</time>${event.stage?badge(t(event.stage)):''}</div><div class="entry-body">${escapeHTML(taskEventText(event))}</div></div></article>`;
}

function phaseMarkup(item){
  const current=stages.indexOf(item.stage);
  return stages.map((stage,index)=>{
    const done=index<current||item.stage==='completed';
    const active=index===current&&item.stage!=='completed';
    const stateText=done?t('phaseDone'):active?t('phaseCurrent'):t('phaseWaiting');
    return `<div class="phase-band-step ${done?'done':active?'active':''}" role="listitem" ${active?'aria-current="step"':''}><span class="phase-node-mark">${done?icon('check'):index+1}</span><span class="phase-node-copy"><strong>${t(stage)}</strong><small>${stateText}</small></span></div>`;
  }).join('');
}

const renderTaskPrototypeLayout=async function(){
  const [item,actors]=await Promise.all([api(`/api/work-items/${state.task}`),loadTaskActors()]);
  const assignee=taskAssignee(item,actors),current=Math.max(1,stages.indexOf(item.stage)+1),terminal=['completed','abandoned'].includes(item.stage);
  const progress=item.stage==='completed'?t('routeComplete'):item.stage==='abandoned'?t('abandoned'):item.blocked_at?t('routeBlocked',{current}):t('routeCurrent',{current,stage:t(item.stage)});
  const badges=`${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.priority))}`;
  $('#workspace').innerHTML=`<header class="task-page-header">
    <button class="back-link" id="back">${icon('chevron')}${t('queue')}</button>
    <div class="task-heading"><div class="task-heading-main"><div class="task-heading-id">${escapeHTML(item.id)} · ${t('version',{version:item.version})}</div><h1>${escapeHTML(item.title)}</h1><div class="task-heading-badges">${badges}</div></div><div class="task-heading-actions"><button class="button" id="message">${t('sendMessage')}</button>${terminal?'':`<button class="button" id="changeAssignee">${t('changeExecutor')}</button><button class="button danger" id="abandonItem">${t('abandonItem')}</button><button class="button primary" id="primaryTaskAction">${t(item.stage==='todo'?'changeExecutor':'stageNext')}</button>`}</div></div>
    <div class="task-meta-strip"><div class="task-meta-item"><span>${t('project')}</span><strong>${escapeHTML(state.project.name)}</strong></div><div class="task-meta-item"><span>${t('executor')}</span><strong>${escapeHTML(assignee.name)}</strong></div><div class="task-meta-item"><span>${t('discussionMode')}</span><strong>${taskModeLabel(item.discussion_mode)}</strong></div><div class="task-meta-item"><span>${t('executionMode')}</span><strong>${taskModeLabel(item.execution_mode)}</strong></div><div class="task-meta-item"><span>${t('acceptanceMode')}</span><strong>${taskModeLabel(item.acceptance_mode)}</strong></div><div class="task-meta-item"><span>${t('updated')}</span><strong>${taskDate(item.updated_at)}</strong></div></div>
    <div class="phase-overview"><div class="phase-overview-head"><span>${t('routeProgress')}</span><strong>${progress}</strong></div><div class="phase-scroll"><div class="phase-band" role="list">${phaseMarkup(item)}</div></div></div>
  </header><div class="task-page-body"><section class="conversation-stream"><div class="conversation-intro"><div><h2>${t('taskDescription')}</h2><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div><div><h2>${t('acceptanceCriteria')}</h2><p>${escapeHTML(item.acceptance_criteria_markdown||t('noCriteria'))}</p></div></div><div class="conversation-timeline">${(item.conversation||[]).map(event=>taskEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</div><div class="conversation-compose"><p>${t('timelineNote')}</p><button class="button primary" id="continueConversation">${t('continueConversation')}</button></div></section></div>`;
  $('#back').onclick=()=>{state.task=null;renderQueue()};
  $('#message').onclick=()=>messageForm(item);$('#continueConversation').onclick=()=>messageForm(item);
  if(!terminal){$('#changeAssignee').onclick=()=>taskAssignmentForm(item,actors);$('#abandonItem').onclick=()=>taskAbandonForm(item);$('#primaryTaskAction').onclick=()=>item.stage==='todo'?taskAssignmentForm(item,actors):stageForm(item)}
};

function taskAssignmentForm(item,actors){
  const choices=actors.filter(actor=>actor.available).map(actor=>`<option value="${actor.kind}:${actor.id}" ${actor.kind===item.assignee_kind&&actor.id===item.assignee_id?'selected':''}>${escapeHTML(actor.name)} · ${t(actor.kind)}</option>`).join('');
  openDrawer(t('changeExecutor'),`<form class="form" id="drawerForm"><label class="field"><span>${t('executor')}</span><select name="assignee" required>${choices}</select></label>${area(t('assignmentReason'),'reason','',`required placeholder="${escapeHTML(t('assignmentReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('confirmAssignment')}</button></form>`,()=>wireForm('#drawerForm',data=>{const [assigneeKind,assigneeId]=data.assignee.split(':');return api(`/api/work-items/${item.id}/assign`,{method:'POST',body:JSON.stringify({assigneeKind,assigneeId,reason:data.reason,expectedVersion:item.version})})}));
}

function taskAbandonForm(item){
  openDrawer(t('abandonItem'),`<form class="form" id="drawerForm">${area(t('abandonReason'),'reason','',`required placeholder="${escapeHTML(t('abandonReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button danger" type="submit">${t('confirmAbandon')}</button></form>`,()=>wireForm('#drawerForm',data=>api(`/api/work-items/${item.id}/abandon`,{method:'POST',body:JSON.stringify({reason:data.reason,expectedVersion:item.version})})));
}

