async function renderRunnerDownloads(){
  const result=await api('/api/runner/downloads');
  const downloads=result.downloads||[];
  const rows=downloads.map(item=>`<a class="runner-download-row" href="${escapeHTML(item.url)}" download="${escapeHTML(item.name)}"><span class="runner-download-icon">${icon('download')}</span><span><strong>${escapeHTML(item.platform)}</strong><small>${escapeHTML(item.arch)} · ${formatDownloadSize(item.size)}</small></span><span class="button primary">${t('download')}</span></a>`).join('');
  $('#workspace').innerHTML=header(t('runnerDownloads'),'')+`<div class="content simple-settings-page"><section class="settings-sheet"><header class="settings-sheet-head"><h2>${t('availableVersions')}</h2><span class="setting-state">${downloads.length}</span></header><div class="runner-download-list">${rows||`<div class="simple-empty-setting"><strong>${t('noRunnerDownloads')}</strong></div>`}</div></section></div>`;
}

function formatDownloadSize(bytes){
  if(bytes<1024*1024)return `${Math.max(1,Math.round(bytes/1024))} KB`;
  return `${(bytes/1024/1024).toFixed(1)} MB`;
}

const renderPageWithoutRunnerDownloads=renderPage;
renderPage=async function(){
  if(state.page==='runnerDownloads')return renderRunnerDownloads();
  return renderPageWithoutRunnerDownloads();
};

