wireForm=function(selector,submit){const form=$(selector);form.onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await submit(Object.fromEntries(new FormData(form)));closeDrawer();await loadProjects();renderShell()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}};

renderShell=function(){
  syncDocumentLocale();
  const projectNav=[['queue','list'],['myQueue','check'],['members','users'],['agents','bot']];
  const bottomNav=[['messages','bell'],['settings','settings']];
  const button=([page,name])=>`<button data-page="${page}" class="${state.page===page?'active':''}">${icon(name)}<span>${t(page)}</span></button>`;
  $('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard</span></div><div class="mast-actions">${localeControl()}</div></header><div class="workspace-grid"><aside class="rail"><button class="project-switch" id="projectSwitch"><span class="project-mark">${state.project?escapeHTML(state.project.key.slice(0,2).toUpperCase()):'--'}</span><span><strong>${escapeHTML(state.project?.name||t('noProjects'))}</strong><small>${escapeHTML(state.project?.repositoryUrl||t('projectSetup'))}</small></span>${icon('chevron')}</button><nav class="nav rail-primary">${projectNav.map(button).join('')}</nav><nav class="nav rail-bottom">${bottomNav.map(button).join('')}</nav><div class="rail-foot">${t('footerRuntime')}<br>${t('footerEmbedded')}</div></aside><main class="workspace" id="workspace"></main></div></div><div class="drawer-backdrop" id="drawerBackdrop"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-hidden="true"></aside>`;
  document.querySelectorAll('[data-page]').forEach(element=>element.onclick=()=>navigate(element.dataset.page));
  wireLocaleControl();$('#projectSwitch').onclick=projectPicker;$('#drawerBackdrop').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});renderPage();
};

renderPage=async function(){
  const root=$('#workspace');root.innerHTML=`<div class="loading">${t('loading')}</div>`;
  try{
    if(state.page==='queue'||state.page==='myQueue')await renderQueue();
    else if(state.page==='members')await renderMembers();
    else if(state.page==='agents')await renderAgents();
    else if(state.page==='messages')await renderMessages();
    else if(state.page==='settings')await renderSettingsHub();
    else await renderQueue();
  }catch(error){root.innerHTML=header(t('loadFailed'),t('loadFailedNote'))+`<div class="content"><div class="form-error">${escapeHTML(error.message)}</div></div>`}
};

function queueMemberOption(actors,value,label){return `<option value="">${t(label)}</option>${actors.filter(actor=>actor.kind==='human').map(actor=>`<option value="${actor.id}" ${value===actor.id?'selected':''}>${escapeHTML(actor.name)}</option>`).join('')}`}

renderQueue=async function(){
  if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}
  const [items,actors]=await Promise.all([api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`),loadTaskActors()]);
  state.items=items;
  if(state.task){await renderTask();return}
  state.queueStage=state.queueStage||'all';state.queueQuery=state.queueQuery||'';state.queuePriority=state.queuePriority||'all';state.queueBlocker=state.queueBlocker||'any';state.expandedParents=state.expandedParents||new Set();
  state.queueCreator=state.queueCreator||'';state.queueAssignee=state.queueAssignee||'';state.queueFollower=state.queueFollower||'';state.queueRelated=state.queueRelated||'';state.queueCreatedByMe=Boolean(state.queueCreatedByMe);
  const mine=state.page==='myQueue';
  const filterActive=state.queueCreatedByMe||state.queuePriority!=='all'||state.queueBlocker!=='any'||state.queueCreator||state.queueAssignee||state.queueFollower||state.queueRelated;
  const stages=[['all','queueAll'],['todo','todo'],['discussion','discussion'],['execution','execution'],['acceptance','acceptance'],['completed','completed'],['order_closed','order_closed']];
  const stageTabs=stages.map(([value,label])=>[value,label,value==='all'?items.length:items.filter(item=>item.stage===value).length]);
  const toolbar=`<div class="app-page-toolbar queue-tools"><label class="search">${icon('search')}<input id="queueSearch" value="${escapeHTML(state.queueQuery)}" placeholder="${t('search')}"></label>${mine?'':`<button class="button ${state.queueCreatedByMe?'active':''}" id="createdByMe" aria-pressed="${state.queueCreatedByMe}">${icon('user')}${t('createdByMe')}</button>`}<button class="button ${filterActive?'active':''}" id="queueFilter">${icon('filter')}${t(filterActive?'filterActive':'filter')}</button><span class="queue-count" id="queueCount"></span></div>`;
  $('#workspace').innerHTML=header(mine?t('myQueue'):t('queue'),mine?t('myQueueNote'):`${state.project.name} · ${t('queueNote')}`,`<button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button>`)+(mine?'':pageTabs(stageTabs,state.queueStage,'queue-stage',t('queueView')))+pageContent(`${toolbar}<div class="queue-content" id="queueList"></div>`,'queue-page-content');
  const matches=item=>{
    const query=state.queueQuery.trim().toLowerCase();
    const followers=item.follower_ids||[];
    const related=id=>item.created_by_user_id===id||(item.assignee_kind==='human'&&item.assignee_id===id)||followers.includes(id);
    return (!mine||(!['completed','abandoned'].includes(item.stage)&&item.assignee_kind==='human'&&item.assignee_id===state.me.id))&&(mine||state.queueStage==='all'||item.stage===state.queueStage)&&(!state.queueCreatedByMe||item.created_by_user_id===state.me.id)&&(!state.queueCreator||item.created_by_user_id===state.queueCreator)&&(!state.queueAssignee||item.assignee_id===state.queueAssignee)&&(!state.queueFollower||followers.includes(state.queueFollower))&&(!state.queueRelated||related(state.queueRelated))&&(state.queuePriority==='all'||item.priority===state.queuePriority)&&(state.queueBlocker==='any'||(state.queueBlocker==='blocked')===Boolean(item.blocked_at))&&(!query||`${item.id} ${item.title}`.toLowerCase().includes(query));
  };
  const paint=()=>{
    let visible=items.filter(matches);
    if(mine)visible.sort((a,b)=>Number(Boolean(b.blocked_at))-Number(Boolean(a.blocked_at))||(queuePriorityRank[a.priority]??9)-(queuePriorityRank[b.priority]??9)||(queueStageRank[a.stage]??9)-(queueStageRank[b.stage]??9)||new Date(a.updated_at)-new Date(b.updated_at));
    $('#queueCount').textContent=t('itemsCount',{count:visible.length});
    $('#queueList').innerHTML=visible.length?`<section class="queue-group"><div class="group-label">${mine?t('myQueue'):t('currentRoute',{count:visible.length})}</div>${visible.map(item=>taskRowMarkup(item,actors,{})).join('')}</section>`:`<section class="queue-empty"><strong>${t('noMatchingItems')}</strong><p>${t('noMatchingItemsNote')}</p></section>`;
    document.querySelectorAll('.work-row[data-id]').forEach(row=>row.onclick=()=>{state.task=row.dataset.id;renderQueue()});
  };
  paint();$('#newItem').onclick=workItemForm;$('#queueSearch').oninput=event=>{state.queueQuery=event.target.value;paint()};$('#queueFilter').onclick=()=>queuePeopleFilterForm(actors);
  const mineButton=$('#createdByMe');if(mineButton)mineButton.onclick=()=>{state.queueCreatedByMe=!state.queueCreatedByMe;renderQueue()};
  document.querySelectorAll('[data-queue-stage]').forEach(button=>button.onclick=()=>{state.queueStage=button.dataset.queueStage;renderQueue()});
};

function queuePeopleFilterForm(actors){
  openDrawer(t('filterWorkItems'),`<form class="form" id="queuePeopleFilter"><div class="filter-member-grid"><label class="field"><span>${t('creator')}</span><select name="creator">${queueMemberOption(actors,state.queueCreator,'allCreators')}</select></label><label class="field"><span>${t('assigneeFilter')}</span><select name="assignee">${queueMemberOption(actors,state.queueAssignee,'allAssignees')}</select></label><label class="field"><span>${t('follower')}</span><select name="follower">${queueMemberOption(actors,state.queueFollower,'allFollowers')}</select></label><label class="field"><span>${t('relatedMember')}</span><select name="related">${queueMemberOption(actors,state.queueRelated,'allRelated')}</select></label></div><label class="field"><span>${t('priority')}</span><select name="priority"><option value="all">${t('allPriorities')}</option>${['urgent','high','medium','low'].map(value=>`<option value="${value}" ${state.queuePriority===value?'selected':''}>${t(value)}</option>`).join('')}</select></label><label class="field"><span>${t('blockerFilter')}</span><select name="blocker"><option value="any">${t('anyBlocker')}</option><option value="blocked" ${state.queueBlocker==='blocked'?'selected':''}>${t('blockedOnly')}</option><option value="unblocked" ${state.queueBlocker==='unblocked'?'selected':''}>${t('unblockedOnly')}</option></select></label><div class="drawer-actions"><button class="button" id="clearQueueFilters" type="button">${t('clearFilters')}</button><button class="button primary" type="submit">${t('applyFilters')}</button></div></form>`,()=>{
    $('#queuePeopleFilter').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));state.queueCreator=data.creator;state.queueAssignee=data.assignee;state.queueFollower=data.follower;state.queueRelated=data.related;state.queuePriority=data.priority;state.queueBlocker=data.blocker;closeDrawer();renderQueue()};
    $('#clearQueueFilters').onclick=()=>{state.queueCreator='';state.queueAssignee='';state.queueFollower='';state.queueRelated='';state.queuePriority='all';state.queueBlocker='any';state.queueCreatedByMe=false;closeDrawer();renderQueue()};
  });
}

workItemForm=async function(){
  const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);
  const activeMembers=members.filter(member=>member.role&&member.status==='active');
  const choices=[...activeMembers.map(member=>`<option value="human:${member.id}">${escapeHTML(member.displayName)} / ${t('human')}</option>`),...agents.filter(agent=>agent.enabled&&agent.status==='active').map(agent=>`<option value="agent:${agent.id}">${escapeHTML(agent.name)} / Agent</option>`)].join('');
  const followers=activeMembers.map(member=>`<label class="member-check"><input type="checkbox" name="followerIds" value="${member.id}"><span class="task-avatar">${taskAvatar(member.displayName)}</span><span>${escapeHTML(member.displayName)}</span>${icon('check')}</label>`).join('');
  openDrawer(t('createItem'),`<form class="form" id="newWorkItemForm">${field(t('title'),'title','text','','required')}${area(t('description'),'descriptionMarkdown')}${area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown','','required')}<label class="field"><span>${t('priority')}</span><select name="priority"><option value="medium">${t('medium')}</option><option value="urgent">${t('urgent')}</option><option value="high">${t('high')}</option><option value="low">${t('low')}</option></select></label><label class="field"><span>${t('assignee')}</span><select name="assignee" required><option value="">${t('selectExecutor')}</option>${choices}</select></label><fieldset class="follower-field"><legend>${t('selectFollowers')}</legend><div class="member-check-list">${followers}</div></fieldset><div class="form-error" hidden></div><button class="button primary" type="submit">${t('createItem')}</button></form>`,()=>{
    $('#newWorkItemForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form));const [assigneeKind,assigneeId]=(data.assignee||'').split(':');button.disabled=true;error.hidden=true;try{await api('/api/work-items',{method:'POST',body:JSON.stringify({...data,assignee:undefined,followerIds:new FormData(form).getAll('followerIds'),assigneeKind,assigneeId,projectId:state.project.id,requestId:crypto.randomUUID()})});closeDrawer();await renderQueue()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}
  });
};

function taskPersonName(id,actors){return actors.find(actor=>actor.id===id&&actor.kind==='human')?.name||t('notSet')}
function taskEventKindLabel(kind){return ({work_item_updated:t('workItemUpdated'),followers_changed:t('followersChanged'),assignment_changed:t('assignmentChanged'),stage_transition:t('stageTransition'),message:t('messageKind')})[kind]||kind.replaceAll('_',' ')}
function chatEventMarkup(event,actors){
  const author=taskEventAuthor(event,actors),own=event.author_type==='human'&&event.author_id===state.me.id;
  if(event.kind!=='message')return `<div class="chat-system-event"><span>${icon('activity')}${escapeHTML(author)} ${escapeHTML(taskEventKindLabel(event.kind))} · ${taskDate(event.created_at)}</span></div>`;
  const attachments=(event.attachments||[]).map(attachment=>attachmentMarkup(attachment)).join('');
  const text=taskEventText(event),onlyAttachment=text==='附件'||text==='Attachments';
  return `<article class="chat-message ${own?'own':''}"><span class="entry-avatar">${taskAvatar(author,'P')}</span><div class="chat-message-content"><div class="entry-head"><strong>${escapeHTML(author)}</strong><time>${taskDate(event.created_at)}</time></div>${onlyAttachment?'':`<div class="chat-bubble">${escapeHTML(text)}</div>`}${attachments?`<div class="chat-attachments">${attachments}</div>`:''}</div></article>`;
}

function formatFileSize(bytes=0){if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${Math.round(bytes/1024)} KB`;return `${(bytes/1024/1024).toFixed(1)} MB`}
function isMarkdownAttachment(attachment){return attachment.mime==='text/markdown'||/\.md$/i.test(attachment.original_name||'')}
function attachmentMarkup(attachment){
  const url=`/api/attachments/${encodeURIComponent(attachment.id)}`,image=(attachment.mime||'').startsWith('image/');
  if(image)return `<figure class="attachment-image"><a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${escapeHTML(attachment.original_name)}" loading="lazy"></a><figcaption>${icon('image')}${escapeHTML(attachment.original_name)} · ${formatFileSize(attachment.size)}</figcaption></figure>`;
  return `<div class="attachment-file"><span>${icon('file')}</span><span><strong>${escapeHTML(attachment.original_name)}</strong><small>${formatFileSize(attachment.size)}</small></span>${isMarkdownAttachment(attachment)?`<button class="text-action" type="button" data-preview-markdown="${attachment.id}">${t('preview')}</button>`:''}<a class="text-action" href="${url}" download>${t('download')}</a></div>${isMarkdownAttachment(attachment)?`<div class="markdown-attachment-preview" id="markdown-${attachment.id}" hidden></div>`:''}`;
}
function safeMarkdown(markdown=''){
  const escaped=escapeHTML(markdown).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  return escaped.split(/\r?\n/).map(line=>{if(/^###\s/.test(line))return `<h4>${line.slice(4)}</h4>`;if(/^##\s/.test(line))return `<h3>${line.slice(3)}</h3>`;if(/^#\s/.test(line))return `<h2>${line.slice(2)}</h2>`;if(/^[-*]\s/.test(line))return `<li>${line.slice(2)}</li>`;return line?`<p>${line}</p>`:'<br>'}).join('');
}
function wireMarkdownPreviews(){document.querySelectorAll('[data-preview-markdown]').forEach(button=>button.onclick=async()=>{const target=$(`#markdown-${CSS.escape(button.dataset.previewMarkdown)}`);if(!target.hidden){target.hidden=true;button.textContent=t('preview');return}button.disabled=true;try{const response=await fetch(`/api/attachments/${encodeURIComponent(button.dataset.previewMarkdown)}`);if(!response.ok)throw new Error(response.statusText);target.innerHTML=safeMarkdown(await response.text());target.hidden=false;button.textContent=t('collapsePreview')}catch(error){toast(error.message)}finally{button.disabled=false}})}
function taskEvidenceMarkup(item){
  const groups=[[t('discussionRecords'),item.conclusions],[t('executionRecords'),item.executions],[t('acceptanceRecords'),item.acceptances]];
  return groups.filter(([,records])=>records?.length).map(([label,records])=>`<section class="task-record-group"><h3>${label}<span>${records.length}</span></h3>${records.map((record,index)=>`<details><summary>${label} ${index+1}<time>${taskDate(record.created_at||record.started_at||record.completed_at)}</time></summary><pre>${escapeHTML(JSON.stringify(record,null,2))}</pre></details>`).join('')}</section>`).join('');
}
function taskBlockForm(item){openDrawer(t('blocker'),`<form class="form" id="blockTaskForm">${area(t('blockReason'),'reason','',`required placeholder="${escapeHTML(t('blockReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button danger" type="submit">${t('confirmBlock')}</button></form>`,()=>wireForm('#blockTaskForm',data=>api(`/api/work-items/${item.id}/block`,{method:'POST',body:JSON.stringify({reason:data.reason,expectedVersion:item.version})})))}

const renderTaskConversationLegacy=async function(){
  const [item,actors]=await Promise.all([api(`/api/work-items/${state.task}`),loadTaskActors()]);
  const assignee=taskAssignee(item,actors),terminal=['completed','abandoned'].includes(item.stage),followers=item.follower_ids||[],creator=taskPersonName(item.created_by_user_id,actors);
  const criteria=(item.acceptance_criteria_markdown||'').split(/\r?\n/).filter(line=>line.trim());
  const attachmentByEntry=new Map();(item.attachments||[]).forEach(attachment=>{if(!attachment.entry_id)return;const list=attachmentByEntry.get(attachment.entry_id)||[];list.push(attachment);attachmentByEntry.set(attachment.entry_id,list)});(item.conversation||[]).forEach(event=>event.attachments=attachmentByEntry.get(event.id)||[]);
  const current=Math.max(1,stages.indexOf(item.stage)+1),progress=item.stage==='completed'?t('routeComplete'):item.stage==='abandoned'?t('abandoned'):item.blocked_at?t('routeBlocked',{current}):t('routeCurrent',{current,stage:t(item.stage)});
  $('#workspace').innerHTML=`<div class="wechat-task"><header class="chat-header"><button class="back-link" id="back">${icon('chevron')}${t(state.page==='myQueue'?'myQueue':'queue')}</button><div class="chat-title"><div><span>${escapeHTML(item.id)} · ${t('version',{version:item.version})}</span><h1>${escapeHTML(item.title)}</h1></div><div class="chat-header-actions"><button class="button" id="manageFollowers">${icon('users')}${t('manageFollowers')}</button>${terminal?'':`<button class="button" id="changeAssignee">${t('changeExecutor')}</button><button class="button ${item.blocked_at?'':'danger'}" id="toggleBlock">${t(item.blocked_at?'clearBlocked':'blockTask')}</button><button class="button danger" id="abandonItem">${t('abandonItem')}</button><button class="button primary" id="primaryTaskAction" ${item.blocked_at?'disabled':''}>${t(item.stage==='todo'?'changeExecutor':'stageNext')}</button>`}</div></div><div class="chat-members"><span class="chat-member-label">${t('assignee')}</span><span class="task-avatar">${taskAvatar(assignee.name)}</span><strong>${escapeHTML(assignee.name)}</strong><i></i><span>${t('creator')} ${escapeHTML(creator)}</span><i></i><span>${t('followers')} ${followers.length}</span><span class="chat-stage">${badge(t(item.stage),'signal')}${badge(t(item.priority))}${item.blocked_at?badge(t('blocked'),'danger'):''}</span></div><div class="task-route-compact"><div><span>${t('routeProgress')}</span><strong>${progress}</strong></div><div class="phase-band" role="list">${phaseMarkup(item)}</div></div></header><main class="chat-canvas"><section class="chat-context"><div class="context-message"><span class="entry-avatar system-avatar">${icon('message')}</span><div><strong>${t('workItemContext')}</strong><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div></div><details class="task-facts"><summary>${icon('list')}${t('taskData')}</summary><dl><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div><div><dt>${t('discussionMode')}</dt><dd>${taskModeLabel(item.discussion_mode)}</dd></div><div><dt>${t('executionMode')}</dt><dd>${taskModeLabel(item.execution_mode)}</dd></div><div><dt>${t('acceptanceMode')}</dt><dd>${taskModeLabel(item.acceptance_mode)}</dd></div><div><dt>${t('updated')}</dt><dd>${taskDate(item.updated_at)}</dd></div><div><dt>${t('dependencies')}</dt><dd>${escapeHTML((item.dependencies||[]).join(', ')||t('none'))}</dd></div>${item.blocked_at?`<div class="blocked-fact"><dt>${t('blocker')}</dt><dd>${escapeHTML(item.blocked_reason||t('blocked'))} · ${taskDate(item.blocked_at)}</dd></div>`:''}</dl>${taskEvidenceMarkup(item)}</details><div class="criteria-message"><div class="criteria-head"><div><strong>${t('acceptanceCriteria')}</strong><small>${t('criteriaDuringWork')}</small></div>${terminal?'':`<button class="text-action" id="editCriteria">${icon('settings')}${t('editCriteria')}</button>`}</div>${criteria.length?`<ol>${criteria.map(line=>`<li><span>${icon('check')}</span><p>${escapeHTML(line.replace(/^[-*]\s*/,''))}</p></li>`).join('')}</ol>`:`<p>${t('noCriteria')}</p>`}</div></section><section class="chat-history">${(item.conversation||[]).map(event=>chatEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</section></main><form class="chat-composer" id="chatComposer"><span class="entry-avatar">${taskAvatar(state.me.displayName)}</span><div class="composer-main"><div class="pending-attachments" id="pendingAttachments" hidden></div><textarea name="markdown" rows="1" placeholder="${t('conversationPlaceholder')}"></textarea></div><label class="attachment-button" title="${t('addAttachment')}">${icon('paperclip')}<input id="attachmentInput" type="file" multiple accept="image/*,.md,.markdown,.txt,.pdf,.zip,.json,.csv"></label><button class="button primary" type="submit">${icon('chevron')}${t('send')}</button></form></div>`;
  $('#back').onclick=()=>{state.task=null;renderQueue()};$('#manageFollowers').onclick=()=>taskFollowersForm(item,actors);const edit=$('#editCriteria');if(edit)edit.onclick=()=>taskCriteriaForm(item);
  const change=$('#changeAssignee');if(change)change.onclick=()=>taskAssignmentForm(item,actors);const action=$('#primaryTaskAction');if(action)action.onclick=()=>item.stage==='todo'?taskAssignmentForm(item,actors):stageForm(item);const abandon=$('#abandonItem');if(abandon)abandon.onclick=()=>taskAbandonForm(item);const toggleBlock=$('#toggleBlock');if(toggleBlock)toggleBlock.onclick=()=>item.blocked_at?stageForm(item):taskBlockForm(item);
  let pendingFiles=[];const input=$('#attachmentInput'),pending=$('#pendingAttachments');input.onchange=()=>{pendingFiles=[...input.files];pending.hidden=!pendingFiles.length;pending.innerHTML=pendingFiles.map((file,index)=>`<span>${icon(file.type.startsWith('image/')?'image':'file')}<span>${escapeHTML(file.name)}<small>${formatFileSize(file.size)}</small></span><button type="button" data-remove-file="${index}" aria-label="${t('removeAttachment')}">${icon('x')}</button></span>`).join('');pending.querySelectorAll('[data-remove-file]').forEach(button=>button.onclick=()=>{pendingFiles.splice(Number(button.dataset.removeFile),1);input.value='';pending.hidden=!pendingFiles.length;button.parentElement.remove()})};
  wireMarkdownPreviews();
  $('#chatComposer').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),markdown=new FormData(form).get('markdown');if(!String(markdown).trim()&&!pendingFiles.length){toast(t('messageOrAttachmentRequired'));return}button.disabled=true;try{const attachmentIds=[];for(const file of pendingFiles){const body=new FormData();body.append('file',file);const uploaded=await api(`/api/work-items/${item.id}/attachments`,{method:'POST',body});attachmentIds.push(uploaded.id)}await api(`/api/work-items/${item.id}/messages`,{method:'POST',body:JSON.stringify({markdown,attachmentIds,expectedVersion:item.version})});await renderTask()}catch(error){toast(error.message);button.disabled=false}};
};

function taskCriteriaForm(item){openDrawer(t('editCriteria'),`<form class="form" id="criteriaForm">${area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown',item.acceptance_criteria_markdown,'required')}<p class="drawer-note">${t('criteriaDuringWork')}</p><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>wireForm('#criteriaForm',data=>api(`/api/work-items/${item.id}`,{method:'PATCH',body:JSON.stringify({...data,expectedVersion:item.version})})));}
function taskFollowersForm(item,actors){const members=actors.filter(actor=>actor.kind==='human'&&actor.available),selected=new Set(item.follower_ids||[]);openDrawer(t('manageFollowers'),`<form class="form" id="followersForm"><div class="member-check-list">${members.map(member=>`<label class="member-check"><input type="checkbox" name="followerIds" value="${member.id}" ${selected.has(member.id)?'checked':''}><span class="task-avatar">${taskAvatar(member.name)}</span><span>${escapeHTML(member.name)}</span>${icon('check')}</label>`).join('')}</div><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{$('#followersForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;try{await api(`/api/work-items/${item.id}/followers`,{method:'PUT',body:JSON.stringify({followerIds:new FormData(form).getAll('followerIds'),expectedVersion:item.version})});closeDrawer();toast(t('followersUpdated'));await renderTask()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});}

async function renderMessages(){
  const notifications=await api(`/api/notifications${state.project?`?projectId=${encodeURIComponent(state.project.id)}`:''}`),unread=notifications.filter(item=>!item.read_at).length;
  $('#workspace').innerHTML=header(t('myMessages'),t('notificationCenter'),unread?`<button class="button" id="markAllRead">${icon('check')}${t('markAllRead')}</button>`:'')+`<div class="content notification-page"><div class="notification-summary"><strong>${unread}</strong><span>${t('unread')}</span></div><div class="notification-list">${notifications.map(item=>`<button class="notification-row ${item.read_at?'':'unread'}" data-notification="${item.id}" data-work-item="${item.work_item_id||''}"><span class="notification-mark">${icon(item.kind==='comment'?'message':item.kind==='assigned'?'users':'activity')}</span><span><small>${escapeHTML(item.title)} · ${taskDate(item.created_at)}</small><strong>${escapeHTML(item.work_item_title||item.work_item_id||'')}</strong><p>${escapeHTML(item.body||'')}</p></span>${item.read_at?'':`<i aria-label="${t('unread')}"></i>`}${icon('chevron')}</button>`).join('')||`<div class="queue-empty"><strong>${t('noNotifications')}</strong><p>${t('noNotificationsNote')}</p></div>`}</div></div>`;
  const readAll=$('#markAllRead');if(readAll)readAll.onclick=async()=>{await api('/api/notifications/read-all',{method:'POST',body:'{}'});renderMessages()};
  document.querySelectorAll('[data-notification]').forEach(row=>row.onclick=async()=>{await api(`/api/notifications/${row.dataset.notification}/read`,{method:'POST',body:'{}'});if(row.dataset.workItem){state.page='queue';state.task=row.dataset.workItem;renderShell()}else renderMessages()});
}

async function renderSettingsHub(){
  state.settingsSection=state.settingsSection||'account';
  const admin=state.me.systemRole==='administrator';
  const sections=[['project','settingsProject'],['account','settingsAccount'],...(admin?[['users','settingsUsers'],['projects','settingsProjects'],['audit','settingsAudit'],['system','settingsSystem'],['runner','settingsRunner']]:[])];
  const renderer={project:renderProjectSettingsPage,account:renderAccount,users:renderUsers,projects:renderProjects,audit:renderActivity,system:renderSystemSettings,runner:renderRunnerDownloads}[state.settingsSection]||renderAccount;
  await renderer();
  const tabs=document.createElement('div');tabs.className='settings-hub-tabs';tabs.innerHTML=sections.map(([key,label])=>`<button class="${state.settingsSection===key?'active':''}" data-setting-section="${key}">${t(label)}</button>`).join('');
  $('#workspace').prepend(tabs);tabs.querySelectorAll('button').forEach(button=>button.onclick=()=>{state.settingsSection=button.dataset.settingSection;renderSettingsHub()});
}

renderMembers=async function(){
  if(!state.project)return renderQueue();
  const data=await api(`/api/projects/${state.project.id}/members`),enabled=data.filter(member=>Boolean(member.role));
  const actions=`<button class="button primary" id="enableMember">${icon('plus')}${t('enableMember')}</button>`;
  const rows=enabled.map(member=>`<button class="table-row action management-row" data-member="${member.id}"><span><strong>${escapeHTML(member.displayName)}</strong><small>@${escapeHTML(member.username)}</small></span><span>${t(member.status)}</span><span>${t(member.systemRole)}</span><span class="row-end">${badge(t(member.role),'signal')}${icon('chevron')}</span></button>`).join('');
  $('#workspace').innerHTML=header(t('members'),t('membersDescription'),actions)+`<div class="content"><div class="table">${rows||`<div class="management-empty">${icon('users')}<strong>${t('noEnabledMembers')}</strong><p>${t('noEnabledMembersNote')}</p></div>`}</div></div>`;
  $('#enableMember').onclick=()=>memberEnablePicker(data);document.querySelectorAll('[data-member]').forEach(row=>row.onclick=()=>memberSettings(data.find(member=>member.id===row.dataset.member)));
};
function memberEnablePicker(members){
  const available=members.filter(member=>!member.role&&member.status==='active');
  if(!available.length){toast(t('allMembersEnabled'));return}
  openDrawer(t('enableMember'),`<form class="form" id="enableMemberForm"><label class="field"><span>${t('chooseMember')}</span><select name="userId" required>${available.map(member=>`<option value="${member.id}">${escapeHTML(member.displayName)} · @${escapeHTML(member.username)}</option>`).join('')}</select></label><label class="field"><span>${t('projectRole')}</span><select name="role"><option value="developer">${t('developer')}</option><option value="viewer">${t('viewer')}</option></select></label><p class="drawer-note">${t('addMemberNote')}</p><div class="form-error" hidden></div><button class="button primary" type="submit">${t('enableMember')}</button></form>`,()=>wireForm('#enableMemberForm',async data=>{await api(`/api/projects/${state.project.id}/members`,{method:'POST',body:JSON.stringify(data)});toast(t('memberEnabledToast'))}));
}

renderAgents=async function(){
  if(!state.project)return renderQueue();
  const data=await api(`/api/projects/${state.project.id}/agents`),enabled=data.filter(agent=>agent.enabled);
  const actions=`<button class="button primary" id="enableAgent">${icon('plus')}${t('enableAgent')}</button>`;
  const rows=enabled.map(agent=>`<button class="table-row action management-row" data-agent="${agent.id}"><span><strong>${escapeHTML(agent.name)}</strong><small>${escapeHTML(agent.purpose||t('noPurpose'))}</small></span><span>${t(agent.status)}</span><span>${t('runnerIdentity')}</span><span class="row-end">${badge(t('enabled'),'signal')}${icon('chevron')}</span></button>`).join('');
  $('#workspace').innerHTML=header(t('agents'),t('agentsDescription'),actions)+`<div class="content"><div class="table">${rows||`<div class="management-empty">${icon('bot')}<strong>${t('noEnabledAgents')}</strong><p>${t('noEnabledAgentsNote')}</p></div>`}</div></div>`;
  $('#enableAgent').onclick=()=>agentEnablePicker(data);document.querySelectorAll('[data-agent]').forEach(row=>row.onclick=()=>agentSettings(data.find(agent=>agent.id===row.dataset.agent)));
};
function agentEnablePicker(agents){
  const available=agents.filter(agent=>!agent.enabled&&agent.status==='active');
  if(!available.length){toast(t('allAgentsEnabled'));return}
  openDrawer(t('enableAgent'),`<form class="form" id="enableAgentForm"><label class="field"><span>${t('chooseAgent')}</span><select name="agentId" required>${available.map(agent=>`<option value="${agent.id}">${escapeHTML(agent.name)} · ${escapeHTML(agent.purpose||t('noPurpose'))}</option>`).join('')}</select></label><p class="drawer-note">${t('agentDisabledNote')}</p><div class="form-error" hidden></div><button class="button primary" type="submit">${t('enableAgent')}</button></form>`,()=>wireForm('#enableAgentForm',async data=>{await api(`/api/projects/${state.project.id}/agents/${encodeURIComponent(data.agentId)}`,{method:'PUT',body:'{}'});toast(t('agentEnabledToast'))}));
}

function localDemoNotifications(){
  if(!['localhost','127.0.0.1','::1'].includes(location.hostname))return [];
  const task=state.items?.[0],taskID=task?.id||'',title=task?.title||'移动端任务队列适配';
  const now=Date.now(),read=new Set(JSON.parse(localStorage.pbDemoNotificationsRead||'[]'));
  return [
    ['assigned','你被指派了任务','需要你确认范围并补充实施方案',4],['mention','有人在讨论中提及你','@admin 请确认 API 兼容范围和回滚方案',18],['comment','任务有新评论','已上传交互截图与验收清单，请查看附件',42],['stage_changed','任务进入执行阶段','讨论结论已冻结，执行者可以开始处理',95],['acceptance_result','验收结果已更新','桌面端通过，窄屏下需要调整页签溢出',190],['blocked_changed','任务阻塞状态已更新','等待测试环境的仓库授权恢复',320]
  ].map(([kind,heading,body,minutes],index)=>({id:`demo-${index}`,project_id:state.project?.id,work_item_id:taskID,kind,title:`${heading} · ${t('localDemoData')}`,body,work_item_title:title,created_at:new Date(now-minutes*60000).toISOString(),read_at:read.has(`demo-${index}`)?new Date().toISOString():null,demo:true}));
}
renderMessages=async function(){
  const live=await api(`/api/notifications${state.project?`?projectId=${encodeURIComponent(state.project.id)}`:''}`),notifications=[...localDemoNotifications(),...live],unread=notifications.filter(item=>!item.read_at).length;
  $('#workspace').innerHTML=header(t('myMessages'),t('notificationCenter'),unread?`<button class="button" id="markAllRead">${icon('check')}${t('markAllRead')}</button>`:'')+`<div class="content notification-page"><div class="notification-summary"><strong>${unread}</strong><span>${t('unread')}</span>${localDemoNotifications().length?badge(t('localDemoData'),'signal'):''}</div><div class="notification-list">${notifications.map(item=>`<button class="notification-row ${item.read_at?'':'unread'}" data-notification="${item.id}" data-work-item="${item.work_item_id||''}" data-demo="${item.demo?'true':'false'}"><span class="notification-mark">${icon(item.kind==='comment'||item.kind==='mention'?'message':item.kind==='assigned'?'users':'activity')}</span><span><small>${escapeHTML(item.title)} · ${taskDate(item.created_at)}</small><strong>${escapeHTML(item.work_item_title||item.work_item_id||'ProjectBoard')}</strong><p>${escapeHTML(item.body||'')}</p></span>${item.read_at?'':`<i aria-label="${t('unread')}"></i>`}${icon('chevron')}</button>`).join('')||`<div class="queue-empty"><strong>${t('noNotifications')}</strong><p>${t('noNotificationsNote')}</p></div>`}</div></div>`;
  const readAll=$('#markAllRead');if(readAll)readAll.onclick=async()=>{localStorage.pbDemoNotificationsRead=JSON.stringify(localDemoNotifications().map(item=>item.id));await api('/api/notifications/read-all',{method:'POST',body:'{}'});renderMessages()};
  document.querySelectorAll('[data-notification]').forEach(row=>row.onclick=async()=>{if(row.dataset.demo==='true'){const ids=new Set(JSON.parse(localStorage.pbDemoNotificationsRead||'[]'));ids.add(row.dataset.notification);localStorage.pbDemoNotificationsRead=JSON.stringify([...ids])}else await api(`/api/notifications/${row.dataset.notification}/read`,{method:'POST',body:'{}'});if(row.dataset.workItem){state.page='queue';state.task=row.dataset.workItem;renderShell()}else renderMessages()});
};

renderProjectSettingsPage=async function(){
  if(!state.project)return renderQueue();
  let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}
  const actions=`<button class="button" id="editProject">${icon('settings')}${t('editProject')}</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}${t('syncRecentCommits')}</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${t(grant?'changeGitAccess':'automaticGitSetup')}</button>`;
  $('#workspace').innerHTML=header(t('settingsProject'),t('settingsOverview'),actions)+`<div class="content project-settings-dashboard"><section class="settings-project-identity"><span class="project-mark large">${escapeHTML(state.project.key.slice(0,2).toUpperCase())}</span><div><small>${t('projectIdentity')} · ${escapeHTML(state.project.key)}</small><h2>${escapeHTML(state.project.name)}</h2><p>${escapeHTML(state.project.repositoryUrl)}</p></div><span class="setting-state ${grant?'blue':''}">${t(grant?'connected':'notConnected')}</span></section><div class="settings-ledger"><section><header><span>${icon('git')}</span><div><h3>${t('authorizationBoundary')}</h3><p>${t('automaticGitNote')}</p></div></header><dl>${grant?`<div><dt>${t('provider')}</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>${t('repository')}</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>${t('accessLevel')}</dt><dd>${t(grant.accessLevel)}</dd></div><div><dt>${t('syncMode')}</dt><dd>${t('onDemand')}</dd></div>`:`<div class="wide"><dt>${t('status')}</dt><dd>${t('noRepositoryGrant')}</dd></div>`}</dl></section><section><header><span>${icon('list')}</span><div><h3>${t('repositoryAndBranches')}</h3><p>${t('version',{version:state.project.configVersion})}</p></div></header><dl><div class="wide"><dt>${t('repositoryURL')}</dt><dd><code>${escapeHTML(state.project.repositoryUrl)}</code></dd></div><div><dt>${t('defaultBranch')}</dt><dd><code>${escapeHTML(state.project.defaultTargetBranch)}</code></dd></div><div><dt>${t('allowedBranches')}</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', ')||t('notSet'))}</dd></div></dl></section><section><header><span>${icon('activity')}</span><div><h3>${t('executionPolicy')}</h3><p>${t('manualExecution')}</p></div></header></section><section><header><span>${icon('shield')}</span><div><h3>${t('credentialPolicy')}</h3><p>${t('secureCredentials')}</p></div></header></section></div></div>`;
  $('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(t('syncResult',{fetched:result.fetched,inserted:result.inserted}))}catch(error){toast(error.message)}finally{sync.disabled=false}};
};

