  input.onchange=()=>{pendingFiles=[...input.files];pending.hidden=!pendingFiles.length;pending.innerHTML=pendingFiles.map((file,index)=>`<span>${icon(file.type.startsWith('image/')?'image':'file')}<span>${escapeHTML(file.name)}<small>${formatFileSize(file.size)}</small></span><button type="button" data-remove-file="${index}" aria-label="${t('removeAttachment')}">${icon('x')}</button></span>`).join('');pending.querySelectorAll('[data-remove-file]').forEach(button=>button.onclick=()=>{pendingFiles.splice(Number(button.dataset.removeFile),1);input.value='';button.parentElement.remove();pending.hidden=!pendingFiles.length})};
  $('#mentionTaskMember').onclick=()=>{const start=textarea.selectionStart??textarea.value.length,end=textarea.selectionEnd??start;textarea.value=`${textarea.value.slice(0,start)}@${textarea.value.slice(end)}`;textarea.focus();textarea.setSelectionRange(start+1,start+1)};
